drop policy if exists "Servants manage attendance for permitted students" on public.attendance_records;
create policy "Servants insert attendance for permitted students" on public.attendance_records for insert to authenticated with check ((select private.current_app_role()) = 'head' or ((select private.current_app_role()) = 'teacher' and (select private.can_access_student(student_id))));
create policy "Servants update attendance for permitted students" on public.attendance_records for update to authenticated using ((select private.current_app_role()) = 'head' or ((select private.current_app_role()) = 'teacher' and (select private.can_access_student(student_id)))) with check ((select private.current_app_role()) = 'head' or ((select private.current_app_role()) = 'teacher' and (select private.can_access_student(student_id))));
create policy "Head deletes attendance records" on public.attendance_records for delete to authenticated using ((select private.current_app_role()) = 'head');
